script:
// TASK: turn a door schedule into a usable, sorted, renumbered schedule published on a titled
// sheet. Runs in a fresh scratch PROJECT document (walls + hosted doors as setup) so it touches no
// open model -- against your real project use the `Document` global and skip the setup block. The
// scratch project stays OPEN after the run; close it by title later (documents-create-write-and-close).
var proj = Connector.CreateProjectDocument();
System.Console.WriteLine("cleanup-title=" + proj.Title + ";");
var levels = new System.Collections.Generic.List<Autodesk.Revit.DB.Level>();
foreach (Autodesk.Revit.DB.Level l in new Autodesk.Revit.DB.FilteredElementCollector(proj).OfClass(typeof(Autodesk.Revit.DB.Level))) levels.Add(l);
levels.Sort((a,b) => a.Elevation.CompareTo(b.Elevation));
var L1 = levels[0]; var L2 = levels.Count > 1 ? levels[1] : levels[0];
Autodesk.Revit.DB.FamilySymbol doorSym = null;
foreach (Autodesk.Revit.DB.FamilySymbol s in new Autodesk.Revit.DB.FilteredElementCollector(proj).OfClass(typeof(Autodesk.Revit.DB.FamilySymbol)).OfCategory(Autodesk.Revit.DB.BuiltInCategory.OST_Doors)) { doorSym = s; break; }
Autodesk.Revit.DB.FamilySymbol tbSym = null;
foreach (Autodesk.Revit.DB.FamilySymbol s in new Autodesk.Revit.DB.FilteredElementCollector(proj).OfClass(typeof(Autodesk.Revit.DB.FamilySymbol)).OfCategory(Autodesk.Revit.DB.BuiltInCategory.OST_TitleBlocks)) { tbSym = s; break; }

// 1. Setup: a wall on each level with hosted doors. Place each door AT its level's elevation --
//    a point below the wall body fails with "Can't cut instance ... out of Wall".
Connector.WithTransaction(proj, () => {
  if (!doorSym.IsActive) doorSym.Activate();
  proj.Regenerate();
  var w1 = Autodesk.Revit.DB.Wall.Create(proj, Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(0,0,0), new Autodesk.Revit.DB.XYZ(30,0,0)), L1.Id, false);
  var w2 = Autodesk.Revit.DB.Wall.Create(proj, Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(0,10,0), new Autodesk.Revit.DB.XYZ(30,10,0)), L2.Id, false);
  proj.Regenerate();
  proj.Create.NewFamilyInstance(new Autodesk.Revit.DB.XYZ(8,0,L1.Elevation), doorSym, w1, L1, Autodesk.Revit.DB.Structure.StructuralType.NonStructural);
  proj.Create.NewFamilyInstance(new Autodesk.Revit.DB.XYZ(20,0,L1.Elevation), doorSym, w1, L1, Autodesk.Revit.DB.Structure.StructuralType.NonStructural);
  proj.Create.NewFamilyInstance(new Autodesk.Revit.DB.XYZ(12,10,L2.Elevation), doorSym, w2, L2, Autodesk.Revit.DB.Structure.StructuralType.NonStructural);
  proj.Regenerate();
  return true;
});

// 2. Create the door schedule and add columns BY PARAMETER ID. Family/Type/Level are 'special'
//    fields whose ids are NEGATIVE BuiltInParameters (ELEM_FAMILY_PARAM, ELEM_TYPE_PARAM,
//    SCHEDULE_LEVEL_PARAM), NOT ALL_MODEL_FAMILY_NAME / ALL_MODEL_TYPE_NAME.
var schedId = Connector.WithTransaction(proj, () => {
  var schedule = Autodesk.Revit.DB.ViewSchedule.CreateSchedule(proj, new Autodesk.Revit.DB.ElementId(Autodesk.Revit.DB.BuiltInCategory.OST_Doors));
  schedule.Name = "Door Schedule (how-to " + System.DateTime.UtcNow.Ticks + ")";
  var def = schedule.Definition;
  string[] names = { "Mark","Family","Type","Level","Width","Height" };
  long[] pids = { (long)Autodesk.Revit.DB.BuiltInParameter.ALL_MODEL_MARK, (long)Autodesk.Revit.DB.BuiltInParameter.ELEM_FAMILY_PARAM, (long)Autodesk.Revit.DB.BuiltInParameter.ELEM_TYPE_PARAM, (long)Autodesk.Revit.DB.BuiltInParameter.SCHEDULE_LEVEL_PARAM, (long)Autodesk.Revit.DB.BuiltInParameter.GENERIC_WIDTH, (long)Autodesk.Revit.DB.BuiltInParameter.DOOR_HEIGHT };
  var byName = new System.Collections.Generic.Dictionary<string, Autodesk.Revit.DB.ScheduleField>();
  for (int i = 0; i < names.Length; i++) { foreach (var sf in def.GetSchedulableFields()) { if (sf.ParameterId.Value == pids[i]) { byName[names[i]] = def.AddField(sf); break; } } }
  // 3. Sort by Level, then Mark.
  def.AddSortGroupField(new Autodesk.Revit.DB.ScheduleSortGroupField(byName["Level"].FieldId));
  def.AddSortGroupField(new Autodesk.Revit.DB.ScheduleSortGroupField(byName["Mark"].FieldId));
  proj.Regenerate();
  return schedule.Id;
});
var sched = proj.GetElement(schedId) as Autodesk.Revit.DB.ViewSchedule;

// 4. Renumber every door D01.. ordered by its ORIGINAL Mark (a stable re-label, not a reshuffle).
var marks = Connector.WithTransaction(proj, () => {
  var doors = new System.Collections.Generic.List<Autodesk.Revit.DB.FamilyInstance>();
  foreach (Autodesk.Revit.DB.FamilyInstance fi in new Autodesk.Revit.DB.FilteredElementCollector(proj).OfCategory(Autodesk.Revit.DB.BuiltInCategory.OST_Doors).WhereElementIsNotElementType()) doors.Add(fi);
  doors.Sort((a,b) => string.CompareOrdinal(a.LookupParameter("Mark") != null ? (a.LookupParameter("Mark").AsString() ?? "") : "", b.LookupParameter("Mark") != null ? (b.LookupParameter("Mark").AsString() ?? "") : ""));
  int n = 1; var outp = new System.Collections.Generic.List<string>();
  foreach (var d in doors) { var m = "D" + n.ToString("00"); d.LookupParameter("Mark").Set(m); outp.Add(m); n++; }
  proj.Regenerate();
  return outp;
});

// 5. Publish the schedule on a titled sheet with ScheduleSheetInstance.Create. A ViewSchedule is
//    NOT a printable/exportable view -- Document.ExportImage/Export on it throws "some of the views
//    is not exportable"; you must place it on a sheet and export the SHEET.
var placed = Connector.WithTransaction(proj, () => {
  if (tbSym != null && !tbSym.IsActive) tbSym.Activate();
  var sheet = Autodesk.Revit.DB.ViewSheet.Create(proj, tbSym != null ? tbSym.Id : Autodesk.Revit.DB.ElementId.InvalidElementId);
  sheet.SheetNumber = "A-DS" + (System.DateTime.UtcNow.Ticks % 100000);
  sheet.Name = "Door Schedule Sheet";
  var ssi = Autodesk.Revit.DB.ScheduleSheetInstance.Create(proj, sheet.Id, sched.Id, new Autodesk.Revit.DB.XYZ(0.3, 0.6, 0));
  proj.Regenerate();
  return new { sheetNumber = sheet.SheetNumber, ssiId = ssi.Id.Value };
});

return new { fieldCount = sched.Definition.GetFieldCount(), marks, placed };
